// Déterminer l'objectif cible et les paramètres
const inputData = $input.item.json.body || $input.item.json || {};
const requestedObjective = inputData.objective || 'sleep';
const batchSize = Number(inputData.batchSize) || 20;

const TEMPLATE_MAP = {
  'sleep': { key: 'story_prompt_sleep', title: 'Histoire du Soir (Sommeil)' },
  'focus': { key: 'story_prompt_focus', title: 'Histoire Focus (Concentration)' },
  'relax': { key: 'story_prompt_relax', title: 'Histoire Détente (Relaxation)' },
  'fun': { key: 'story_prompt_fun', title: 'Histoire Ludique (S\'amuser)' }
};

const target = TEMPLATE_MAP[requestedObjective] || { key: `story_prompt_${requestedObjective}`, title: `Objectif ${requestedObjective}` };

return {
  json: {
    template_key: target.key,
    objective: requestedObjective,
    title: target.title,
    batch_size: batchSize
  }
};

// Agrégation des retours critiques IA + retours parents réels
const targetContext = $('Préparer Paramètres').item.json;
const activePromptData = $('Récupérer Prompt Actuel').item.json;
const storiesBatch = $input.all().map(i => i.json);

let currentPrompt = '';
if (Array.isArray(activePromptData) && activePromptData.length > 0) {
  currentPrompt = activePromptData[0].active_content || '';
} else if (activePromptData && activePromptData.active_content) {
  currentPrompt = activePromptData.active_content;
}

// 1. Analyse des retours utilisateurs (Notes étoiles & commentaires)
const ratedStories = storiesBatch.filter(s => s.user_rating != null);
const userRatings = ratedStories.map(s => Number(s.user_rating));
const avgUserRating = userRatings.length > 0 
  ? (userRatings.reduce((a, b) => a + b, 0) / userRatings.length).toFixed(1) 
  : 'N/A';

const userComments = storiesBatch
  .filter(s => s.user_comment && s.user_comment.trim())
  .map(s => ({ rating: s.user_rating, comment: s.user_comment }));

// 2. Analyse des critiques IA
const critiqueScores = storiesBatch.filter(s => s.critique_score != null).map(s => Number(s.critique_score));
const avgCritiqueScore = critiqueScores.length > 0 
  ? (critiqueScores.reduce((a, b) => a + b, 0) / critiqueScores.length).toFixed(1) 
  : 'N/A';

// Extraction des faiblesses récurrentes
const weaknessesList = [];
const strengthsList = [];
const actionableList = [];
let excessiveOnomatopoeiaCount = 0;
let moralizingCount = 0;

storiesBatch.forEach(s => {
  if (Array.isArray(s.weaknesses)) {
    s.weaknesses.forEach(w => {
      if (w.issue) weaknessesList.push({ issue: w.issue, impact: w.impact, severity: w.severity });
    });
  }
  if (Array.isArray(s.strengths)) {
    s.strengths.forEach(st => {
      if (st.aspect) strengthsList.push({ aspect: st.aspect, analysis: st.analysis });
    });
  }
  if (Array.isArray(s.actionable_improvements)) {
    s.actionable_improvements.forEach(act => {
      if (act.recommendation) actionableList.push(act.recommendation);
    });
  }
  if (s.calmi_pitfalls) {
    if (s.calmi_pitfalls.excessive_onomatopoeia) excessiveOnomatopoeiaCount++;
    if (s.calmi_pitfalls.heavy_moralizing_detected) moralizingCount++;
  }
});

const userPrompt = `Voici les données pour l'objectif: ${targetContext.title} (Clé: ${targetContext.template_key})\n\n--- PROMPT ACTUEL ---\n${currentPrompt}\n\n--- STATISTIQUES DU LOT (${storiesBatch.length} histoires) ---\n- Note moyenne des parents : ${avgUserRating}/5 (sur ${ratedStories.length} avis)\n- Score technique moyen IA : ${avgCritiqueScore}/10\n- Alertes onomatopées excessives : ${excessiveOnomatopoeiaCount}\n- Alertes moralisation lourde : ${moralizingCount}\n\n--- COMMENTAIRES REELS DES PARENTS ---\n${JSON.stringify(userComments, null, 2)}\n\n--- PRINCIPALES FAIBLESSES TECHNIQUES DETECTEES ---\n${JSON.stringify(weaknessesList.slice(0, 12), null, 2)}\n\n--- POINTS FORTS A CONSERVER ---\n${JSON.stringify(strengthsList.slice(0, 8), null, 2)}\n\n--- RECOMMANDATIONS D'ACTION IA ---\n${JSON.stringify(actionableList.slice(0, 10), null, 2)}\n\nGénère la nouvelle version optimisée du template au format JSON requis.`;

const openaiPayload = {
  model: "gpt-5.6-terra",
  response_format: { type: "json_object" },
  messages: [
    {
      role: "system",
      content: "Tu es le Directeur Éditorial et Pédagogique en Chef de Calmi. Ton rôle est de perfectionner continuellement les templates de prompts de génération d'histoires pour enfants.\n\nTu disposes :\n1. Du template de prompt actuellement utilisé pour l'objectif ciblé.\n2. Des retours réels des parents/enfants (notes étoiles et commentaires libres).\n3. Des analyses critiques techniques générées par le module qualité (faiblesses récurrentes, pièges Calmi détectés tels que la moralisation lourde ou les onomatopées superflues, points forts à sanctuariser).\n\nCONSIGNES CALMI IMPORTANTES :\n- Préserves scrupuleusement la structure et les balises variables indispensables du prompt (ex: {child_name}, {target_age}, {duration}, etc.).\n- Renforces les règles 'Show Don't Tell', la musicalité de lecture à voix haute, et la douceur émotionnelle.\n- Si les parents signalent une peur, une longueur inadaptée ou un manque d'engagement, intègre des consignes explicites et bien calibrées pour y remédier.\n- Tu dois répondre EXCLUSIVEMENT sous la forme d'un objet JSON valide contenant :\n  - \"improved_prompt\": le texte complet et révisé du template de prompt.\n  - \"changelog\": un résumé clair, vulgarisé et concis (en français) expliquant ce qui a été amélioré et pourquoi (en citant les retours parents et critiques corrigées).\n  - \"key_improvements\": une liste de 3 à 5 points clés d'amélioration."
    },
    {
      role: "user",
      content: userPrompt
    }
  ]
};

return {
  json: {
    template_key: targetContext.template_key,
    objective: targetContext.objective,
    title: targetContext.title,
    current_prompt: currentPrompt,
    openai_payload: openaiPayload,
    stats: {
      total_stories: storiesBatch.length,
      rated_count: ratedStories.length,
      avg_user_rating: avgUserRating,
      avg_critique_score: avgCritiqueScore,
      excessive_onomatopoeia_count: excessiveOnomatopoeiaCount,
      heavy_moralizing_count: moralizingCount
    }
  }
};

// Extraire la réponse JSON de gpt-5.6-terra
const rawResponse = $input.item.json;
const synthContext = $('Synthèse Retours & Critiques').item.json;

let parsedResult = {};
try {
  const messageContent = rawResponse.choices[0].message.content;
  parsedResult = typeof messageContent === 'string' ? JSON.parse(messageContent) : messageContent;
} catch (err) {
  throw new Error(`Erreur lors du parsing de la réponse gpt-5.6-terra: ${err.message}`);
}

const improvedPrompt = parsedResult.improved_prompt || '';
const changelog = parsedResult.changelog || 'Optimisation automatique continue par gpt-5.6-terra';
const keyImprovements = Array.isArray(parsedResult.key_improvements) 
  ? parsedResult.key_improvements.join(' | ') 
  : '';

const fullChangelog = `🤖 Auto-n8n (gpt-5.6-terra) — ${changelog}${keyImprovements ? ` [Points clés: ${keyImprovements}]` : ''}`;

return {
  json: {
    template_key: synthContext.template_key,
    objective: synthContext.objective,
    title: synthContext.title,
    new_content: improvedPrompt,
    changelog: fullChangelog,
    stats: synthContext.stats
  }
};

